🛠️ Yardımcı Fonksiyonlar
Yerel klasörlerdeki veri dosyalarının konumunu otomatik tespit eden fonksiyon
bul_dosya &lt;- function(adaylar) { olasi_yollar &lt;- unlist( map(adaylar, ~ c(file.path(“data”, .x), .x)) ) bulunan &lt;- olasi_yollar[file.exists(olasi_yollar)]
if (length(bulunan) == 0) { stop( paste0( “Dosya bulunamadı. Aranan adaylar:”, paste(adaylar, collapse = “,”), “proje klasörüne veya data/ klasörüne koyunuz.” ) ) }
bulunan[1] }
bul_dosya_opsiyonel &lt;- function(adaylar) { olasi_yollar &lt;- unlist( map(adaylar, ~ c(file.path(“data”, .x), .x)) ) bulunan &lt;- olasi_yollar[file.exists(olasi_yollar)]
if (length(bulunan) == 0) { return(NA_character_) }
bulunan[1] }
Karakter olarak gelen sayısal değerleri sayı formatına dönüştüren temizleme fonksiyonu
hacim_sayi &lt;- function(x) { if (is.numeric(x)) { return(as.numeric(x)) }
x &lt;- as.character(x) x &lt;- str_squish(x) x &lt;- str_replace_all(x, “\s”, ““) x &lt;- str_replace_all(x,”\.”, ““) x &lt;- str_replace_all(x,”,“,”.”) as.numeric(x) }
Yüzdelik verileri sayısal formata dönüştüren fonksiyon
yuzde_sayi &lt;- function(x) { if (is.numeric(x)) { return(as.numeric(x)) }
x &lt;- as.character(x) x &lt;- str_squish(x) x &lt;- str_replace_all(x, “%”, ““)
if_else( str_detect(x, “,”), as.numeric(str_replace(str_replace_all(x, “\.”, ““),”,“,”.”)), as.numeric(x) ) }
Türkçe ay sıralama standartları
ay_sirasi_buyuk &lt;- c( “OCAK”, “ŞUBAT”, “MART”, “NİSAN”, “MAYIS”, “HAZİRAN”, “TEMMUZ”, “AĞUSTOS”, “EYLÜL”, “EKİM”, “KASIM”, “ARALIK” )
ay_sirasi &lt;- c( “Ocak”, “Şubat”, “Mart”, “Nisan”, “Mayıs”, “Haziran”, “Temmuz”, “Ağustos”, “Eylül”, “Ekim”, “Kasım”, “Aralık” )
ay_tablosu &lt;- tibble( ay_no = 1:12, ay = factor(ay_sirasi, levels = ay_sirasi, ordered = TRUE), ay_buyuk = ay_sirasi_buyuk )

📈 Dağıtılan, Çekilen ve Kişi Başı Çekilen Su Verisi
kullanim_dosya &lt;- bul_dosya_opsiyonel( c( “dagitilan_cekilen.xls”, “dagitilan_cekilen.xlsx”, “DAGITILAN CEKILEN VE KIS BASI CEKILEN.xls”, “DAGITILAN CEKILEN VE KIS BASI CEKILEN.xlsx”, “DAGITILAN CEKILEN VE KISI BASI CEKILEN.xls” ) )
if (!is.na(kullanim_dosya)) { raw_kullanim &lt;- read_excel(kullanim_dosya, col_names = FALSE)
su_kullanim &lt;- raw_kullanim |&gt; slice(6:n()) |&gt; transmute( yil = as.numeric(…2), dagitilan_su_m3 = hacim_sayi(…3), cekilen_su_bin_m3 = hacim_sayi(…4), kisi_basi_litre_gun = hacim_sayi(…5) ) |&gt; filter(!is.na(yil)) |&gt; mutate( dagitilan_su_milyon_m3 = dagitilan_su_m3 / 1e6, cekilen_su_milyon_m3 = cekilen_su_bin_m3 / 1000 ) } else { su_kullanim &lt;- tibble() }
if (nrow(su_kullanim) &gt; 0) { su_kullanim |&gt; head(10) |&gt; kable(digits = 2, caption = “Dağıtılan, çekilen ve kişi başı çekilen su verisi”) |&gt; kable_styling(full_width = FALSE) } else { tibble( bilgi = “Dağıtılan/çekilen su dosyası bulunamadı. Bu bölüm atlanacaktır.” ) |&gt; kable(caption = “Dosya durumu”) |&gt; kable_styling(full_width = FALSE) }

🗺️ Suyun Kaynaklara Göre Dağılımı
kaynak_dosya &lt;- bul_dosya_opsiyonel( c( “sular_nereden_geliyor.xls”, “sular_nereden_geliyor.xlsx”, “sular nereden geliyor.xls”, “sular nereden geliyor.xlsx” ) )
if (!is.na(kaynak_dosya)) { raw_kaynak &lt;- read_excel(kaynak_dosya, col_names = FALSE)
su_kaynak &lt;- raw_kaynak |&gt; slice(6:n()) |&gt; transmute( yil = as.numeric(…2), akarsu = hacim_sayi(…3), baraj = hacim_sayi(…4), golet = hacim_sayi(…5), kaynak = hacim_sayi(…6), kuyu = hacim_sayi(…7) ) |&gt; filter(!is.na(yil)) |&gt; mutate(across(akarsu:kuyu, ~ replace_na(.x, 0)))
su_kaynak_long &lt;- su_kaynak |&gt; pivot_longer( cols = akarsu:kuyu, names_to = “kaynak_turu”, values_to = “su_bin_m3” ) |&gt; mutate( kaynak_turu = str_to_title(kaynak_turu, locale = “tr”), su_milyon_m3 = su_bin_m3 / 1000 ) } else { su_kaynak &lt;- tibble() su_kaynak_long &lt;- tibble() }
if (nrow(su_kaynak_long) &gt; 0) { su_kaynak_long |&gt; head(10) |&gt; kable(digits = 2, caption = “Suyun kaynaklara göre dağılımı”) |&gt; kable_styling(full_width = FALSE) } else { tibble( bilgi = “Sular nereden geliyor dosyası bulunamadı. Kaynak kompozisyonu bölümü atlanacaktır.” ) |&gt; kable(caption = “Dosya durumu”) |&gt; kable_styling(full_width = FALSE) }

🚰 Su Kullanımı Analizi
if (nrow(su_kullanim) &gt; 0) { p6 &lt;- ggplot(su_kullanim, aes(x = yil, y = dagitilan_su_milyon_m3)) + geom_line(color = “#8e44ad”, linewidth = 1.1) + geom_point(color = “#9b59b6”, size = 3) + labs( title = “Ankara’da Dağıtılan Su Miktarı”, x = “Yıl”, y = “Dağıtılan Su (Milyon m³)” ) + theme_minimal() ggplotly(p6) }
if (nrow(su_kullanim) &gt; 0) { p7 &lt;- ggplot(su_kullanim, aes(x = yil, y = cekilen_su_milyon_m3)) + geom_line(color = “#27ae60”, linewidth = 1.1) + geom_point(color = “#2ecc71”, size = 3) + labs( title = “İçme ve Kullanma Suyu İçin Çekilen Toplam Su”, x = “Yıl”, y = “Çekilen Su (Milyon m³)” ) + theme_minimal() ggplotly(p7) }
if (nrow(su_kullanim) &gt; 0) { p8 &lt;- ggplot(su_kullanim, aes(x = yil, y = kisi_basi_litre_gun)) + geom_line(color = “#d35400”, linewidth = 1.1) + geom_point(color = “#e67e22”, size = 3) + geom_hline( yintercept = mean(su_kullanim$kisi_basi_litre_gun, na.rm = TRUE), linetype = “dashed”, color = “#7f8c8d” ) + labs( title = “Kişi Başı Günlük Çekilen Su Miktarı”, subtitle = “Kesikli çizgi dönem ortalamasını göstermektedir.”, x = “Yıl”, y = “Litre / Kişi-Gün” ) + theme_minimal() ggplotly(p8) }
Dağıtılan ve çekilen su miktarının yıllar içinde doğrusal bir eğilimle artması, Ankara’nın kentsel gelişim ve nüfus artışı dinamiklerinin doğrudan bir sonucudur. Kişi başı günlük su çekim miktarının zaman zaman dalgalanması ise şebeke kayıp-kaçak oranları, kentsel dönüşümle yenilenen altyapı ve hanehalkı tasarruf eğilimleri ile açıklanabilmektedir.

🌊 Su Kaynakları Analizi
if (nrow(su_kaynak_long) &gt; 0) { p9 &lt;- ggplot(su_kaynak_long, aes(x = factor(yil), y = su_milyon_m3, fill = kaynak_turu)) + geom_col() + scale_fill_brewer(palette = “Set2”) + labs( title = “Ankara İçme ve Kullanma Suyunun Kaynaklara Göre Dağılımı”, x = “Yıl”, y = “Çekilen Su (Milyon m³)”, fill = “Kaynak Türü” ) + theme_minimal() ggplotly(p9) }
if (nrow(su_kaynak_long) &gt; 0) { su_kaynak_pay &lt;- su_kaynak_long |&gt; group_by(yil) |&gt; mutate( pay = su_bin_m3 / sum(su_bin_m3, na.rm = TRUE) ) |&gt; ungroup()
p10 &lt;- ggplot(su_kaynak_pay, aes(x = factor(yil), y = pay, fill = kaynak_turu)) + geom_col(position = “fill”) + scale_y_continuous(labels = percent) + scale_fill_brewer(palette = “Set2”) + labs( title = “Su Kaynaklarının Yüzdesel Payı”, x = “Yıl”, y = “Pay”, fill = “Kaynak Türü” ) + theme_minimal() ggplotly(p10) }
Kaynak kompozisyonu analizi, Ankara’nın su şebekesinde yüzeysel biriktirme yapısı olan barajların mutlak ve baskın bir stratejik role sahip olduğunu açıkça ortaya koymaktadır. Akarsular ve yeraltı kuyularının payının kısıtlı kalması, baraj havzalarındaki doluluk oranlarını kentsel su arz güvenliğinin yegane belirleyicisi kılmaktadır.

📈 Dağıtılan Su Trend Modeli
if (nrow(su_kullanim) &gt; 0) { model_dagitilan &lt;- lm(dagitilan_su_milyon_m3 ~ yil, data = su_kullanim)
tidy(model_dagitilan) |&gt; kable(digits = 4, caption = “Dağıtılan su trend modeli katsayıları”) |&gt; kable_styling(full_width = FALSE)
glance(model_dagitilan) |&gt; select(r.squared, adj.r.squared, sigma, statistic, p.value) |&gt; kable(digits = 4, caption = “Dağıtılan su trend modeli uyum ölçütleri”) |&gt; kable_styling(full_width = FALSE) }
if (nrow(su_kullanim) &gt; 0) { p11 &lt;- ggplot(su_kullanim, aes(x = yil, y = dagitilan_su_milyon_m3)) + geom_point(size = 3, color = “#8e44ad”) + geom_smooth(method = “lm”, se = TRUE, color = “#9b59b6”) + labs( title = “Dağıtılan Su Miktarı İçin Doğrusal Trend”, x = “Yıl”, y = “Dağıtılan Su (Milyon m³)” ) + theme_minimal() ggplotly(p11) }
